sys_script_include.script:
var trigger_revoke_workflow = Class.create();
trigger_revoke_workflow.prototype = {
    initialize: function() {},
    execute: function(ritm_sys_id) {
        try {
            var log = new GlideRecord('x_avx_appviewx_aut_logs');
            // Get the RITM record to access its variables
            var ritmGR = new GlideRecord('sc_req_item');
            ritmGR.get(ritm_sys_id);
            var form = ritmGR.variables;
            var company = form.company_name;
            log.initialize();
            var client_id;

            if (gs.getProperty("glide.sys.domain.partitioning") === 'true') {
                var gr = new GlideRecordSecure('x_avx_appviewx_aut_connection_settings_table');
                gr.addQuery('company', company);
                gr.query();
                if (!gr.hasNext()) {
                    throw "Could not find AppViewX instance url to fetch the details.";
                }
                while (gr.next()) {
                    var url = gr.getValue('instance_url') || '';
                    var mid_server = gr.getValue('mid_server') || '';
                    var cmdb_sync = gr.getDisplayValue('enable_appviewx_inventory_sync') || 'false';
                }
            } else {
                url = gs.getProperty("x_avx_appviewx_aut.URL");
                mid_server = gs.getProperty("x_avx_appviewx_aut.MID Server Name");
                cmdb_sync = gs.getProperty("x_avx_appviewx_aut.CMDB Sync");
            }
            var r = new sn_ws.RESTMessageV2();
            var script_include_call = new appviewx_oauth_token_generation();
            var token_generation = script_include_call.TestConnection(client_id, company);
            if (token_generation.length == 2 && token_generation[0] == 200) {
                var parse_response = JSON.parse(token_generation[1]);
                var token = parse_response['response'];
            } else {
                throw "Error while generating the Token.";
            }
            var ca_tag_name = form.ca_tag_name;
            var gr_clm = new GlideRecord('x_avx_appviewx_aut_clm_settings');
            gr_clm.addQuery('ca_tag_name', ca_tag_name);
            gr_clm.query();
            if (!gr_clm.hasNext()) {
                throw "Could not find CA Tag with the name - " + ca_tag_name + " in the CLM Settings table";
            }
            gr_clm.next();

			var first_level_mail = "";
			var second_level_mail = "";
			var appviewx_approval;
			if(gr_clm.use_approval_settings_from_create == "true"){
				appviewx_approval = gr_clm.approval_levels_in_appviewx;
				first_level_mail = gr_clm.appviewx_one_level_approval_mail_id_for_create;
				second_level_mail = gr_clm.appviewx_two_level_approval_mail_id_for_create;
			}else{
				appviewx_approval = gr_clm.is_approval_needed_in_appviewx_revoke;
				first_level_mail = gr_clm.appviewx_one_level_approval_mail_id_for_revoke;
				second_level_mail = gr_clm.appviewx_two_level_approval_mail_id_for_revoke;
			}

            log.level = 'Info';
            log.script = 'revoke_certificate';
            log.application = 'AppViewX';
            log.message = 'Triggering new certificate request API';
            log.insert();
            var payload = {
                "payload": {
                    "header": {
                        "workflowName": (gr_clm.workflow_name_for_revoke_appviewx || '').toString()
                    },
                    "data": {
                        "input": {
                            "requestData": [{
                                "sequenceNo": 1,
                                "scenario": "scenario",
                                "fieldInfo": {
                                    "common_name": (form.common_name || '').toString(),
                                    "serial_number": (form.serial_number || '').toString(),
                                    "reason": (form.reason || '').toString(),
                                    "comments": (form.comments || '').toString(),
                                    "email_id": (form.email_id || '').toString(),
                                    "ritm_number": (ritmGR.number || '').toString(),
                                    "appviewx_approval": (gr_clm.is_approval_needed_in_appviewx_revoke || '').toString(),
                                    "one_level_mail_id": (first_level_mail || '').toString(),
                                    "two_level_mail_id": (second_level_mail || '').toString(),
                                    "sys_id": (ritmGR.sys_id || '').toString(),
                                    "req_number": (ritmGR.request.getDisplayValue() || '').toString(),
                                    "req_sys_id": (ritmGR.request || '').toString(),
                                    "requestor_id": (ritmGR.requested_for.email || '').toString(),
                                    "cmdb_sync": (cmdb_sync || '').toString(),
                                    "catalog_task": (gr_clm.create_catalog_task_ticket || '').toString()
                                }
                            }]
                        },
                        "globalData": {},
                        "task_action": 1
                    }
                }
            };
            gs.info(JSON.stringify(payload));
            log.level = 'Info';
            log.script = 'revoke_certificate';
            log.application = 'AppViewX';
            log.message = JSON.stringify(payload);
            log.insert();
            if (mid_server != "") {
                r.setMIDServer(mid_server);
                r.setEccParameter('skip_sensor', 'true');
                r.setEccCorrelator('AVX_REST_CALL');
            }
            r.setHttpMethod("post");
            r.setRequestHeader("token", token);
            r.setRequestHeader('User-Agent', 'snow');
            r.setRequestHeader("Content-Type", "application/json");
            r.setEndpoint(url + "/avxapi/visualworkflow-submit-request?gwsource=web");
            r.setRequestBody(JSON.stringify(payload));
            var response = r.executeAsync();
            var reqRecord = ritmGR.request.getRefRecord();
            if (response.haveError()) {
                var responseMessage = response.getErrorMessage() || '';
                var responseBody = response.getBody() || '';
                log.level = 'Error';
                log.script = 'revoke_certificate_request';
                log.application = 'AppViewX';
                log.message = 'Certificate request failed ' + responseBody + '\nMessage: ' + responseMessage;
                log.insert();
                responseBody = JSON.parse(responseBody);
                form.request_id = "Failed to submit certificate request";
                form.appviewx_response = responseBody["message"];
                ritmGR.stage = "closed_incomplete";
                ritmGR.state = 4;
                // Set the values on the request table
                reqRecord.state = 4;
                reqRecord.request_state = "closed_incomplete";
                reqRecord.update();
                ritmGR.comments = "Failure while processing the service request.\n" + responseBody["message"];
				ritmGR.update();
                return "false";
            } else {
                responseBody = response.getBody();
                responseBody = JSON.parse(responseBody);
                var avx_id = responseBody["response"]["requestId"];
                log.level = 'Info';
                log.script = 'revoke_certificate_request';
                log.application = 'AppViewX';
                log.message = 'Successfully triggered appviewx workflow with request ID ' + avx_id;
                log.insert();
                var message = responseBody["response"]["message"] + "Status : " + responseBody["response"]["status"];
                form.request_id = "R" + avx_id;
                form.appviewx_response = message;
				ritmGR.update();
                return "true";
            }
        } catch (error) {
            log.level = 'Error';
            log.script = 'revoke_certificate_request';
            log.application = 'AppViewX';
            log.message = 'Response for request with number ' + ritmGR.number + '\n ' + error;
            log.insert();
            ritmGR.comments = "Failure while processing the service request.";
            ritmGR.stage = "closed_incomplete";
            ritmGR.state = 4;
            reqRecord = ritmGR.request.getRefRecord();
            reqRecord.state = 4;
            reqRecord.request_state = "closed_incomplete";
            reqRecord.update();
            gs.addErrorMessage(error);
			ritmGR.update();
            return "false";
        }
    },

    type: 'trigger_revoke_workflow'
};
